import itertools, random, sys, importlib.util, time
spec = importlib.util.spec_from_file_location("main", "/workspace/submission/main.py")
main = importlib.util.module_from_spec(spec); spec.loader.exec_module(main)
POW3 = main.POW3

def naive_marg(factors, order_vars, m):
    """Reference: per-target specialization + plain elimination."""
    Z = main.partition_value(factors, order_vars)
    marg = []
    for v in range(m):
        nums = []
        for t in range(3):
            spec_f = []
            for scope, tab in factors:
                if v in scope:
                    j = scope.index(v)
                    nscope = tuple(x for x in scope if x != v)
                    ntab = []
                    step_lo = POW3[j]; step_hi = POW3[j+1]
                    for a in range(len(tab)):
                        if (a // step_lo) % 3 == t:
                            ntab.append(tab[a])
                    # re-encode: positions above j shift down
                    out = [0]*POW3[len(nscope)]
                    for a, val in enumerate(tab):
                        if (a // step_lo) % 3 != t: continue
                        lo = a % step_lo; hi = a // step_hi
                        out[lo + hi*step_lo] += val
                    if nscope: spec_f.append((nscope, out))
                    else: spec_f.append(((), out))
                else:
                    spec_f.append((scope, tab))
            rest = [w for w in order_vars if w != v]
            nums.append(main.partition_value(spec_f, rest))
        marg.append(nums)
    return Z, marg

def brute(factors, m):
    Z = 0; marg = [[0,0,0] for _ in range(m)]
    for assign in itertools.product(range(3), repeat=m):
        W = 1
        for scope, tab in factors:
            idx = 0
            for j, v in enumerate(scope): idx += assign[v]*POW3[j]
            W *= tab[idx]
            if W == 0: break
        Z += W
        if W:
            for v in range(m): marg[v][assign[v]] += W
    return Z, marg

def ktree_factors(rng, m, k=4, zero_prob=0.15):
    """Random graph with elimination order 0..m-1 of width <= k, plus factors."""
    later = [[] for _ in range(m)]
    clique_edges = set()
    for i in range(m-1, -1, -1):
        cand = list(range(i+1, m))
        # choose up to k later vertices forming a clique
        best = []
        rng.shuffle(cand)
        for c in cand:
            if all((min(x,c),max(x,c)) in clique_edges for x in best):
                best.append(c)
                if len(best) == k: break
        later[i] = best
        for a in range(len(best)):
            for b in range(a+1, len(best)):
                clique_edges.add((min(best[a],best[b]), max(best[a],best[b])))
    factors = []
    for i in range(m):
        pool = [i] + later[i]
        # a couple of factors per variable over random subsets containing i
        for _ in range(rng.randint(1,2)):
            extra = [x for x in pool if x != i and rng.random() < 0.7]
            scope = tuple(sorted([i]+extra))
            size = POW3[len(scope)]
            tab = [rng.choice([0,0,1,2,3,5,7,11,1000000,999983]) if rng.random() > zero_prob else 0 for _ in range(size)]
            factors.append((scope, tab))
    return factors, list(range(m))

seed = int(sys.argv[1]); trials = int(sys.argv[2])
rng = random.Random(seed)
bad = 0
for tr in range(trials):
    m = rng.randint(1, 9)
    factors, order = ktree_factors(rng, m)
    Zb, mb = brute(factors, m)
    Zp = main.partition_value(factors, order)
    reduced = main.reduce_factors(factors)
    if reduced is None:
        # some phi is identically zero -> Z must be 0
        assert Zb == 0, ("reduce said zero but brute Z>0", Zb)
        continue
    Zj, mj = main.infer_joint(reduced, order, m)
    scale = Zb // Zj if Zj else 0
    ok = (Zp == Zb)
    if Zb == 0:
        ok = ok and (Zj == 0)
    else:
        ok = ok and Zj > 0 and Zb * Zj == Zj * Zb
        for v in range(m):
            for t in range(3):
                ok = ok and mj[v][t] * Zb == mb[v][t] * Zj
    if not ok:
        bad += 1
        print("MISMATCH brute/joint", m, factors, Zb, Zj, mb, mj); break
    if Zj:
        Zn, mn = naive_marg(factors, order, m)
        ok2 = Zn == Zb
        for v in range(m):
            for t in range(3):
                ok2 = ok2 and mn[v][t]*Zb == mb[v][t]*Zn
        if not ok2:
            bad += 1; print("MISMATCH brute/naive", m, factors, Zb, Zn); break
print("trials", trials, "bad", bad)
